<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class Squad extends Model { protected $fillable=['organization_id','tournament_id','team_id','name','min_players','max_players','status','created_by']; protected $casts=['min_players'=>'integer','max_players'=>'integer']; public function organization():BelongsTo{return $this->belongsTo(Organization::class);} public function tournament():BelongsTo{return $this->belongsTo(Tournament::class);} public function team():BelongsTo{return $this->belongsTo(Team::class);} public function players():HasMany{return $this->hasMany(SquadPlayer::class);} public function matchSquads():HasMany{return $this->hasMany(MatchSquad::class);} }